277	void FLAC__bitreader_free(FLAC__BitReader *br)
278	{
279		FLAC__ASSERT(0 != br);
280	
281		if(0 != br->buffer)
282			free(br->buffer);
283		br->buffer = 0;
284		br->capacity = 0;
285		br->words = br->bytes = 0;
286		br->consumed_words = br->consumed_bits = 0;
287		br->read_callback = 0;
288		br->client_data = 0;
289	}
